// GENERATED by `npm run reminders` from index.ts + decide.ts: paste this whole file into the Supabase dashboard editor.
// Edit index.ts / decide.ts instead (the app's tests check decide.ts).

// Supabase Edge Function "send-reminders" (Deno). Called every 15 minutes by pg_cron (see supabase/notifications.sql)
// with the x-cron-secret header. For each person: which reminder is due in her own time zone (decide.ts, the same code
// the app's tests check), written to notification_log first so nothing is sent twice, then sent by Web Push to each of
// her devices. Subscriptions the push service says are gone (404/410) are deleted.
//
// Secrets (Edge Functions → Secrets): CRON_SECRET, VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY, VAPID_SUBJECT (the app's https address;
// no email is used).
// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are provided by Supabase automatically. "Verify JWT" must be OFF.
//
// To paste into the dashboard editor, use paste-in-dashboard.ts (this file with decide.ts inlined; `npm run reminders`).

import webpush from 'npm:web-push@3.6.7';
import { createClient } from 'npm:@supabase/supabase-js@2.118.0';

// ---- decide.ts (inlined)
type ReminderKind = 'daily' | 'streak' | 'weekly';

interface ReminderPrefs {
  user_id: string;
  /** IANA time zone, e.g. "Africa/Cairo" */
  tz: string;
  /** 'f' or 'm': the wording */
  gender: string;
  daily_on: boolean;
  /** "HH:MM", her local time */
  daily_time: string;
  streak_on: boolean;
  streak_time: string;
  weekly_on: boolean;
  /** local date (YYYY-MM-DD) of her last voice workout */
  last_workout_date: string | null;
  /** days in a row, as of her last workout */
  streak: number;
  /** local date the weekly check becomes due */
  weekly_due_date: string | null;
}

interface Reminder {
  kind: ReminderKind;
  /** the local day it belongs to (the dedupe key with the user and kind) */
  date: string;
  title: string;
  body: string;
  /** where tapping it opens, relative to the app */
  url: string;
}

const WINDOW_MINUTES = 15;

/** Local date and minutes since midnight at `now` in `tz` (an unknown zone falls back to UTC). */
function localTime(now: Date, tz: string): { date: string; minutes: number } {
  let parts: Intl.DateTimeFormatPart[];
  try {
    parts = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(now);
  } catch {
    parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'UTC', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(now);
  }
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? '00';
  const hour = Number(get('hour')) % 24;
  return { date: `${get('year')}-${get('month')}-${get('day')}`, minutes: hour * 60 + Number(get('minute')) };
}

/** "19:30" → 1170; anything odd → null. */
function parseTime(t: string | null | undefined): number | null {
  const m = /^(\d{1,2}):(\d{2})/.exec(t ?? '');
  if (!m) return null;
  const h = Number(m[1]);
  const min = Number(m[2]);
  return h < 24 && min < 60 ? h * 60 + min : null;
}

/** If `time` is in the current window: the local date it belongs to (the window may have started before midnight). */
function dueDate(now: Date, tz: string, time: string): string | null {
  const t = parseTime(time);
  if (t === null) return null;
  const local = localTime(now, tz);
  const since = (local.minutes - t + 1440) % 1440;
  if (since >= WINDOW_MINUTES) return null;
  return localTime(new Date(now.getTime() - since * 60000), tz).date;
}

/** The day before a YYYY-MM-DD date. */
function previousDay(date: string): string {
  const d = new Date(date + 'T12:00:00Z');
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}

const AR_DIGITS = '٠١٢٣٤٥٦٧٨٩';
const ar = (n: number) => String(n).replace(/\d/g, (d) => AR_DIGITS[Number(d)]);

/** The wording, girl or boy. */
function reminderText(kind: ReminderKind, gender: string, streak = 0): { title: string; body: string } {
  const boy = gender === 'm';
  if (kind === 'weekly') return { title: 'صوتي', body: '📏 وقت القياس الأسبوعي' };
  if (kind === 'streak') {
    const days = streak === 2 ? 'اليومين' : streak <= 10 ? `الـ${ar(streak)} أيام` : `الـ${ar(streak)} يوم`;
    return { title: 'صوتي', body: `🔥 لسه ${boy ? 'ما اتمرنتش' : 'ما اتمرنتيش'} النهارده — ${boy ? 'متضيعش' : 'متضيعيش'} ${days} ورا بعض` };
  }
  return { title: 'صوتي', body: '🎤 وقت تمرين النهارده — ١٠ دقايق بس' };
}

/**
 * The reminders due now for one person, given the kinds already sent (`sent` holds "kind|date" keys from the log).
 *  - at the daily time: the weekly check on the day it becomes due (instead of the daily reminder), otherwise the daily
 *    reminder, unless she has already done today's workout;
 *  - at the evening time: "streak at risk" when the streak is at least 2, her last workout was yesterday (so today's is
 *    still missing), and no daily/weekly reminder went out within the hour before it.
 */
function dueReminders(p: ReminderPrefs, now: Date, sent: Set<string>): Reminder[] {
  const out: Reminder[] = [];
  const was = (kind: ReminderKind, date: string) => sent.has(`${kind}|${date}`);
  const add = (kind: ReminderKind, date: string, url: string) => {
    if (was(kind, date)) return;
    out.push({ kind, date, url, ...reminderText(kind, p.gender, p.streak) });
  };

  const dailyDay = dueDate(now, p.tz, p.daily_time);
  if (dailyDay) {
    if (p.weekly_on && p.weekly_due_date === dailyDay) add('weekly', dailyDay, '#/path');
    else if (p.daily_on && p.last_workout_date !== dailyDay) add('daily', dailyDay, '#/path');
  }

  const streakDay = dueDate(now, p.tz, p.streak_time);
  if (streakDay && p.streak_on && p.streak >= 2 && p.last_workout_date === previousDay(streakDay)) {
    const daily = parseTime(p.daily_time);
    const evening = parseTime(p.streak_time)!;
    const sameHour = daily !== null && (evening - daily + 1440) % 1440 < 60;
    const dailyWent = out.length > 0 || was('daily', streakDay) || was('weekly', streakDay);
    if (!(sameHour && dailyWent)) add('streak', streakDay, '#/path');
  }
  return out;
}
// ---- end of decide.ts

/** Who sends the pushes, for the push services: the app's address (the spec allows an https URL instead of an email). */
const SUBJECT = 'https://mariamaher86-svg.github.io/soty/';

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json' } });

Deno.serve(async (req: Request) => {
  const secret = Deno.env.get('CRON_SECRET');
  if (!secret || req.headers.get('x-cron-secret') !== secret) return json({ error: 'forbidden' }, 401);

  const url = Deno.env.get('SUPABASE_URL')!;
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const sb = createClient(url, serviceKey, { auth: { persistSession: false } });
  webpush.setVapidDetails(Deno.env.get('VAPID_SUBJECT') || SUBJECT, Deno.env.get('VAPID_PUBLIC_KEY')!, Deno.env.get('VAPID_PRIVATE_KEY')!);

  const now = new Date();
  const { data: prefs, error } = await sb.from('notification_prefs').select('*');
  if (error) return json({ error: error.message }, 500);

  let sent = 0;
  let removed = 0;
  for (const p of (prefs ?? []) as ReminderPrefs[]) {
    // what already went out today or yesterday (a window can start before her midnight)
    const today = localTime(now, p.tz).date;
    const { data: log } = await sb.from('notification_log').select('kind, local_date').eq('user_id', p.user_id).in('local_date', [today, previousDay(today)]);
    const already = new Set((log ?? []).map((r: { kind: string; local_date: string }) => `${r.kind}|${r.local_date}`));
    const due = dueReminders(p, now, already);
    if (!due.length) continue;

    const { data: subs } = await sb.from('push_subscriptions').select('endpoint, p256dh, auth').eq('user_id', p.user_id);
    for (const r of due) {
      // claim it first: the unique key (user, kind, local date) means a second run can't send it again
      const { error: dup } = await sb.from('notification_log').insert({ user_id: p.user_id, kind: r.kind, local_date: r.date });
      if (dup) continue;
      const payload = JSON.stringify({ title: r.title, body: r.body, url: r.url, tag: r.kind });
      for (const s of (subs ?? []) as { endpoint: string; p256dh: string; auth: string }[]) {
        try {
          await webpush.sendNotification({ endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } }, payload, { TTL: 60 * 60 * 6, urgency: 'normal' });
          sent++;
        } catch (e) {
          const code = (e as { statusCode?: number }).statusCode;
          if (code === 404 || code === 410) {
            await sb.from('push_subscriptions').delete().eq('endpoint', s.endpoint);
            removed++;
          }
        }
      }
    }
  }
  return json({ ok: true, people: prefs?.length ?? 0, sent, removed });
});
